package neon.androidplayer

internal data class ShaderPreset(val id:String,val title:String,val load:String,val description:String)
internal fun shaderCatalog():List<ShaderPreset> = buildList {
    add(ShaderPreset("native","Без шейдеров","Минимальная","Обычное масштабирование mpv. Начни с него при нагреве, пропуске кадров или несовместимости GPU."))
    add(ShaderPreset("sd480","480p · FSRCNNX + Krig + deband","Тяжёлый","Увеличение низкого разрешения, восстановление цветовых границ и уменьшение цветовых ступеней. Для SD-видео; может смягчить мелкую фактуру."))
    add(ShaderPreset("hd720","720p · FSRCNNX + Krig","Тяжёлый","Нейросетевое увеличение и обработка цветности без принудительного deband. Для 720p на более высоком разрешении; сравни с оригиналом на живом видео."))
    add(ShaderPreset("ravu","RAVU · лёгкий","Лёгкий","Увеличение детализации контуров с меньшей нагрузкой относительно нейросетевых цепочек. Подходит как первый вариант для обычного видео; возможна излишняя резкость."))
    add(ShaderPreset("fsrcnnx8","FSRCNNX 8 + Krig","Средний / тяжёлый","Компактная нейросетевая цепочка увеличения с обработкой цветности. Для источника ниже разрешения экрана; нагрузка растёт с размером кадра."))
    add(ShaderPreset("fsrcnnx16","FSRCNNX 16 + Krig","Очень тяжёлый","Более крупная нейросетевая модель увеличения. Для мощного GPU и заметного увеличения кадра; на телефоне возможны нагрев и пропуски кадров."))
    add(ShaderPreset("sharp","SSimSuperRes","Средний / тяжёлый","Дополнительная обработка масштабированного изображения. Для сравнения деталей на увеличенном кадре; чрезмерная резкость может подчеркнуть шум и сжатие."))
    for(tier in listOf("fast","hq"))for(mode in listOf("a","b","c","aa","bb","ca")) {
        val title=mapOf("a" to "A","b" to "B","c" to "C","aa" to "A+A","bb" to "B+B","ca" to "C+A").getValue(mode)
        val stage=when(mode){"c","ca"->"Включает увеличение с подавлением шума.";"b","bb"->"Использует мягкое восстановление линий.";else->"Включает восстановление и увеличение линий."}
        add(ShaderPreset("anime-$tier-$mode","Anime4K $title · ${tier.uppercase()}",if(tier=="fast")"Средний / тяжёлый"else "Очень тяжёлый",
            "Для аниме и рисованного изображения. $stage ${if(mode.length==2)"Дополнительный проход повышает нагрузку. "else ""}${if(tier=="hq")"HQ использует более крупные модели."else "Fast — более компактные модели."} На живом видео может искажать фактуру; сравни с оригиналом."))
    }
}
